# Run this in PowerShell from your project root: C:\sf\nfl-fantasy-starter
# Writes each file exactly, byte-for-byte.

$b64 = ""
[System.IO.File]::WriteAllText("$PWD\scripts\poll-live-week.ts", [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64)))
Write-Host "Wrote scripts/poll-live-week.ts"

$b64 = ""
[System.IO.File]::WriteAllText("$PWD\package.json", [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64)))
Write-Host "Wrote package.json"

$b64 = ""
[System.IO.File]::WriteAllText("$PWD\README.md", [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64)))
Write-Host "Wrote README.md"

Write-Host "`nVerifying..."
Select-String -LiteralPath "scripts\poll-live-week.ts" -Pattern "isWeekFullyFinal" -Quiet
Select-String -LiteralPath "package.json" -Pattern "poll:week" -Quiet
Select-String -LiteralPath "README.md" -Pattern "poll-live-week" -Quiet
Write-Host "If all lines above say True, the files landed correctly."
Write-Host "`nRun: npm install   (only needed if this is the first time using this script -- no new deps were added, this is just a safety net)"